from collections import deque
def comps(grid):
    H,W=len(grid),len(grid[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if not seen[r][c]:
                col=grid[r][c]; q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    x,y=q.popleft(); cells.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and not seen[a][b] and grid[a][b]==col:
                            seen[a][b]=True; q.append((a,b))
                out.append((len(cells),col,cells))
    return sorted(out,reverse=True)
